INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '截面图', 'kp-xc-tutui-spatial-section', CAST($${"type":"doc","content":[{"type":"heading","attrs":{"level":1},"content":[{"type":"text","text":"截面图"}]},{"type":"highlightBlock","attrs":{"backgroundColor":"#fffbeb","borderColor":"#f59e0b","icon":"💡"},"content":[{"type":"paragraph","content":[{"type":"text","text":"核心结论：","marks":[{"type":"bold"}]},{"type":"text","text":"截面图考查用平面切割立体图形后得到的截面形状。正方体截面最多是六边形，圆柱截面可以是椭圆，圆锥截面可以是抛物线。"}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"一、题型识别"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"给出立体图形，问切割后截面形状"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"给出截面形状，判断能否从某立体切出"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"二、核心规律"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"正方体截面：三角形、四边形（含梯形）、五边形、六边形（不可能是七边形以上）"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"圆柱截面：圆、矩形、椭圆、抛物线+直线、双曲线+直线"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"圆锥截面：圆、三角形、椭圆、抛物线+直线、双曲线+直线"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"三、易错点"}]},{"type":"highlightBlock","attrs":{"backgroundColor":"#fef2f2","borderColor":"#ef4444","icon":"⚠️"},"content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"正方体截面不可能是七边形或以上"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"截面一定是平面切割，不能是曲面"}]}]}]}]},{"type":"highlightBlock","attrs":{"backgroundColor":"#eff6ff","borderColor":"#3b82f6","icon":"📊"},"content":[{"type":"paragraph","content":[{"type":"text","text":"刷题建议：","marks":[{"type":"bold"}]},{"type":"text","text":"截面图在图形推理中占比约 2%，属于低频考点。重点记忆正方体和圆柱的截面形状范围。"}]}]}]}$$ AS jsonb), NULL, '图形推理立体类-截面图的核心考点：正方体截面、圆柱截面、圆锥截面。', category_node.id, CAST('["图形推理", "立体空间", "截面图", "正方体截面"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xc_tuTui_spatial_section", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, extra = EXCLUDED.extra, updated_time = NOW();
